// String → scaled integer, without parseFloat or Number() (technical-design.md §Decimal strategy, ADR-002).

export type ParseCode = 'NOT_NUMBER' | 'NEGATIVE' | 'TOO_MANY_DP';

/** `value` is the number × 10^maxDp as an exact integer; `null` means the field is empty. */
export type ParseResult = { ok: true; value: number | null } | { ok: false; code: ParseCode };

/** Above every limit (1,000,000 × 100 and 100 × 10), so a saturated value only ever fails a range check. */
export const OVER_LIMIT = 1_000_000_000_000;

/** More integer digits than this saturate to OVER_LIMIT, keeping every value a safe integer. */
const MAX_INT_DIGITS = 9;

/** Digits with at most one dot (A-13); the integer or fraction part may be empty. */
const DECIMAL = /^(\d*)(?:\.(\d*))?$/;

/** Folds a string of ASCII digits into an integer, one digit at a time. */
function digitsValue(digits: string): number {
  let value = 0;
  for (let i = 0; i < digits.length; i += 1) value = value * 10 + (digits.charCodeAt(i) - 48);
  return value;
}

/**
 * Checks, in A-15 order: not a number → negative → too many decimal places.
 * Spaces around the text are ignored; "" and a lone "." are empty (A-18); a lone "-" is negative (A-18).
 */
export function parseDecimal(raw: string, maxDp: number): ParseResult {
  const text = raw.trim();
  if (text === '' || text === '.') return { ok: true, value: null };

  const negative = text.startsWith('-');
  const match = DECIMAL.exec(negative ? text.slice(1) : text);
  if (match === null) return { ok: false, code: 'NOT_NUMBER' };
  if (negative) return { ok: false, code: 'NEGATIVE' };

  const intDigits = (match[1] ?? '').replace(/^0+/, '');
  const fracDigits = match[2] ?? '';
  if (fracDigits.length > maxDp) return { ok: false, code: 'TOO_MANY_DP' };
  if (intDigits.length > MAX_INT_DIGITS) return { ok: true, value: OVER_LIMIT };

  return { ok: true, value: digitsValue(intDigits + fracDigits.padEnd(maxDp, '0')) };
}
import { parseDecimal, type ParseCode } from './parse';

// Per-field checks in A-15 order (technical-design.md §Validation). Nothing throws; every result is typed.

export type EarnedCode = ParseCode | 'OVER_TOTAL';
export type TotalCode = ParseCode | 'ZERO' | 'TOO_LARGE';
export type PassCode = ParseCode | 'TOO_LARGE';

/** `value` is a scaled integer (earned and total × 100, pass mark × 10); `null` = empty field. */
export type FieldResult<Code> = { ok: true; value: number | null } | { ok: false; code: Code };

export interface RawFields {
  readonly earned: string;
  readonly total: string;
  readonly pass: string;
}

export interface ValidatedFields {
  readonly earned: FieldResult<EarnedCode>;
  readonly total: FieldResult<TotalCode>;
  readonly pass: FieldResult<PassCode>;
}

const MARKS_DP = 2; // A-4
const PASS_DP = 1; // A-6
const TOTAL_MAX = 100_000_000; // 1,000,000 marks × 100 (A-5)
const PASS_MAX = 1000; // 100 % × 10 (A-6)

function validateTotal(raw: string): FieldResult<TotalCode> {
  const parsed = parseDecimal(raw, MARKS_DP);
  if (!parsed.ok || parsed.value === null) return parsed;
  if (parsed.value === 0) return { ok: false, code: 'ZERO' };
  if (parsed.value > TOTAL_MAX) return { ok: false, code: 'TOO_LARGE' };
  return parsed;
}

function validatePass(raw: string): FieldResult<PassCode> {
  const parsed = parseDecimal(raw, PASS_DP);
  if (!parsed.ok || parsed.value === null) return parsed;
  if (parsed.value > PASS_MAX) return { ok: false, code: 'TOO_LARGE' };
  return parsed;
}

/** Marks earned ≤ total is checked only when both are otherwise valid and filled in (A-15). */
function validateEarned(raw: string, total: FieldResult<TotalCode>): FieldResult<EarnedCode> {
  const parsed = parseDecimal(raw, MARKS_DP);
  if (!parsed.ok || parsed.value === null) return parsed;
  if (total.ok && total.value !== null && parsed.value > total.value) return { ok: false, code: 'OVER_TOTAL' };
  return parsed;
}

export function validateInputs(raw: RawFields): ValidatedFields {
  const total = validateTotal(raw.total);
  return { earned: validateEarned(raw.earned, total), total, pass: validatePass(raw.pass) };
}
/**
 * The single catalogue of user-facing text (M-1..M-40, docs/user-stories.md).
 * UI code never hard-codes text: it reads it from here.
 * Templates keep their placeholders ({n}, {total}, …); helpers below fill them.
 */

import { formatMarks } from './logic/format';
import type { Gap } from './logic/gap';

export const MESSAGE_IDS = [
  'M-1', 'M-2', 'M-3', 'M-4', 'M-5', 'M-6', 'M-7', 'M-8', 'M-9', 'M-10',
  'M-11', 'M-12', 'M-13', 'M-14', 'M-15', 'M-16', 'M-17', 'M-18', 'M-19', 'M-20',
  'M-21', 'M-22', 'M-23', 'M-24', 'M-25', 'M-26', 'M-27', 'M-28', 'M-29', 'M-30',
  'M-31', 'M-32', 'M-33', 'M-34', 'M-35', 'M-36', 'M-37', 'M-38', 'M-39', 'M-40',
] as const;

export type MessageId = (typeof MESSAGE_IDS)[number];

export const MESSAGES = {
  // Result area and verdict
  'M-1': 'Enter marks earned and total marks possible to see the score.',
  'M-2': 'Enter a pass mark to see whether this is a pass or a fail.',
  'M-3': 'The score will appear once every entry is valid.',
  'M-4': 'Pass',
  'M-5': 'Fail',
  // Gap line ({n}: at most 2 dp, trailing zeros trimmed, comma thousands)
  'M-6': '{n} marks short of the pass mark',
  'M-7': '1 mark short of the pass mark',
  'M-8': '{n} marks above the pass mark',
  'M-9': '1 mark above the pass mark',
  'M-10': 'Exactly on the pass mark',
  'M-11': 'Less than 0.01 marks above the pass mark',
  // Under marks earned
  'M-12': 'Marks earned must be a number, like 17.5.',
  'M-13': "Marks earned can't be negative.",
  'M-14': 'Marks earned can have at most 2 decimal places.',
  'M-15': "Marks earned can't be more than the total marks possible.",
  // Under total marks possible
  'M-16': 'Total marks possible must be a number, like 23.',
  'M-17': "Total marks possible can't be negative.",
  'M-18': 'Total marks possible can have at most 2 decimal places.',
  'M-19': 'Total marks possible must be more than 0.',
  'M-20': "Total marks possible can't be more than 1,000,000.",
  // Under pass mark
  'M-21': 'Pass mark must be a number, like 70.',
  'M-22': "Pass mark can't be negative.",
  'M-23': 'Pass mark can have at most 1 decimal place.',
  'M-24': "Pass mark can't be more than 100.",
  // Actions (M-26..M-29 are for future stories S-5, S-6)
  'M-25': 'Next learner',
  'M-26': 'Copy outcome',
  'M-27': 'Outcome copied.',
  'M-28': '{earned} of {total} marks: {score}, {verdict}, {gap line}',
  'M-29': 'Marks needed to pass: {n} of {total}',
  // Page and card text (DEC-11)
  'M-30': 'Quiz score and pass-mark calculator',
  'M-31': 'Quiz score',
  'M-32': 'Check a quiz result',
  'M-33': 'A score at or above the pass mark is a pass.',
  'M-34': 'Marks earned',
  'M-35': 'Total marks possible',
  'M-36': 'Pass mark',
  'M-37': ' (percent)',
  'M-38': '%',
  'M-39': 'Score',
  'M-40': 'or press Esc',
} as const satisfies Record<MessageId, string>;

/** The key name at the end of M-40, shown in a <kbd> element. */
export const ESC_KEY_LABEL = 'Esc';

/** The unit after a score ("76.0%"): the same percent sign as M-38. */
export const SCORE_UNIT = MESSAGES['M-38'];

/** A score as read out: "76.0" → "76.0%". */
export function scoreText(score: string): string {
  return `${score}${SCORE_UNIT}`;
}

/** Joins the parts of a screen-reader announcement (ui-design.md §Accessibility): "76.0%, Pass". */
export function announcementText(parts: ReadonlyArray<string>): string {
  return parts.join(', ');
}

/** One mark, in hundredths: the only value that takes the singular "mark" (A-11). */
const ONE_MARK = 100;

/** The gap line (M-6..M-11) for a gap, with {n} filled by `formatMarks` (A-10, A-11). */
export function gapText(gap: Gap): string {
  switch (gap.kind) {
    case 'exact':
      return MESSAGES['M-10'];
    case 'aboveTiny':
      return MESSAGES['M-11'];
    case 'short':
      return gap.h === ONE_MARK ? MESSAGES['M-7'] : MESSAGES['M-6'].replace('{n}', formatMarks(gap.h));
    case 'above':
      return gap.h === ONE_MARK ? MESSAGES['M-9'] : MESSAGES['M-8'].replace('{n}', formatMarks(gap.h));
  }
}
import { renderResult, renderShell, type ShellElements } from './render';
import { toViewModel, type RawInputs } from './view-model';

/** Screen-reader status text is set this long after the last input, so "17.5" is read once (ui-design.md). */
const ANNOUNCE_DELAY_MS = 500;

function readInputs(shell: ShellElements): RawInputs {
  return { earned: shell.inputs.earned.value, total: shell.inputs.total.value, pass: shell.inputs.pass.value };
}

/** Debounced writer for the role="status" node; it writes only text that differs from the last one. */
function createAnnouncer(status: HTMLElement): (text: string) => void {
  let timer: number | undefined;
  let lastText = '';
  return (text) => {
    window.clearTimeout(timer);
    timer = window.setTimeout(() => {
      if (text === lastText) return;
      status.textContent = text;
      lastText = text;
    }, ANNOUNCE_DELAY_MS);
  };
}

/** Mounts the app into `root` and recalculates on every input event (A-7: no Calculate button). */
export function mountApp(root: HTMLElement | null): ShellElements | null {
  if (root === null) return null;
  const shell = renderShell(root);
  const announce = createAnnouncer(shell.status);

  const update = (): void => {
    const vm = toViewModel(readInputs(shell));
    renderResult(shell.resultBody, vm); // visual update is immediate
    announce(vm.announcement);
  };

  for (const input of Object.values(shell.inputs)) input.addEventListener('input', update);
  update();
  return shell;
}
/** Tiny DOM builder: creates an element with attributes and children (strings become text nodes). */
export function el<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  attrs: Record<string, string> = {},
  children: ReadonlyArray<Node | string> = [],
): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag);
  for (const [name, value] of Object.entries(attrs)) node.setAttribute(name, value);
  node.append(...children);
  return node;
}

const SVG_NS = 'http://www.w3.org/2000/svg';

/** Same as `el`, for inline SVG icons (which need the SVG namespace). */
export function svgEl<K extends keyof SVGElementTagNameMap>(
  tag: K,
  attrs: Record<string, string> = {},
  children: ReadonlyArray<Node> = [],
): SVGElementTagNameMap[K] {
  const node = document.createElementNS(SVG_NS, tag);
  for (const [name, value] of Object.entries(attrs)) node.setAttribute(name, value);
  node.append(...children);
  return node;
}
import { ESC_KEY_LABEL, MESSAGES, SCORE_UNIT } from '../messages';
import { el, svgEl } from './dom';
import type { GapKind, Verdict, ViewModel } from './view-model';

export type FieldName = 'earned' | 'total' | 'pass';

export interface ShellElements {
  readonly inputs: Readonly<Record<FieldName, HTMLInputElement>>;
  readonly errors: Readonly<Record<FieldName, HTMLParagraphElement>>;
  readonly resultBody: HTMLDivElement;
  readonly status: HTMLDivElement;
  readonly nextLearner: HTMLButtonElement;
}

/** Initial values on load and after reload (technical-design.md §State model). */
export const INITIAL_VALUES: Readonly<Record<FieldName, string>> = { earned: '', total: '', pass: '70' };

const FIELD_IDS: Readonly<Record<FieldName, string>> = { earned: 'earned', total: 'total', pass: 'pass-mark' };

function createInput(field: FieldName): HTMLInputElement {
  const input = el('input', {
    class: 'input',
    id: FIELD_IDS[field],
    name: field,
    type: 'text',
    inputmode: 'decimal',
    autocomplete: 'off',
    spellcheck: 'false',
    'aria-describedby': `${FIELD_IDS[field]}-error`,
  });
  input.value = INITIAL_VALUES[field];
  return input;
}

function createErrorSlot(field: FieldName): HTMLParagraphElement {
  return el('p', { class: 'field-error', id: `${FIELD_IDS[field]}-error` });
}

function createField(
  field: FieldName,
  labelChildren: ReadonlyArray<Node | string>,
  input: HTMLInputElement,
  error: HTMLParagraphElement,
): HTMLDivElement {
  const control =
    field === 'pass'
      ? el('div', { class: 'input-wrap' }, [input, el('span', { class: 'suffix', 'aria-hidden': 'true' }, [MESSAGES['M-38']])])
      : input;
  return el('div', { class: `field field--${field}` }, [
    el('label', { class: 'label', for: FIELD_IDS[field] }, labelChildren),
    control,
    error,
  ]);
}

/** A muted message in the result body, e.g. the idle prompt M-1; no score. */
function resultMessage(text: string): HTMLParagraphElement {
  return el('p', { class: 'result-msg' }, [text]);
}

/** Tick (Pass) and cross (Fail) glyphs from the mockup, drawn on a 24 × 24 grid. */
const VERDICT_GLYPHS: Readonly<Record<Verdict, string>> = {
  pass: 'M6.5 12.5l3.8 3.8 7.4-8.3',
  fail: 'M8 8l8 8M16 8l-8 8',
};

/** Score "76.0" with the half-size muted "%" unit. */
function scoreNode(score: string): HTMLParagraphElement {
  return el('p', { class: 'score' }, [score, el('span', { class: 'score-unit' }, [SCORE_UNIT])]);
}

/** Verdict block: decorative tick/cross disc + the word, so the verdict never relies on colour alone. */
function verdictNode(verdict: Verdict, text: string): HTMLParagraphElement {
  const glyph = svgEl('svg', { viewBox: '0 0 24 24', 'aria-hidden': 'true', focusable: 'false' }, [
    svgEl('path', { class: 'i-stroke', d: VERDICT_GLYPHS[verdict] }),
  ]);
  return el('p', { class: `verdict verdict--${verdict}` }, [
    el('span', { class: 'verdict-disc' }, [glyph]),
    el('span', {}, [text]),
  ]);
}

/** Gap-line arrows from the mockup on a 16 × 16 grid: ▲ above, ▼ short, "=" exactly on. */
const GAP_ICONS: Readonly<Record<GapKind, { readonly tone: Verdict; readonly path: string }>> = {
  above: { tone: 'pass', path: 'M8 3.5l5 7H3z' },
  aboveTiny: { tone: 'pass', path: 'M8 3.5l5 7H3z' },
  exact: { tone: 'pass', path: 'M3 5.5h10v2H3zM3 9.5h10v2H3z' },
  short: { tone: 'fail', path: 'M8 12.5l5-7H3z' },
};

/** Gap line: decorative arrow + the words, which carry the meaning (never colour alone). */
function gapNode(kind: GapKind, text: string): HTMLParagraphElement {
  const icon = GAP_ICONS[kind];
  const glyph = svgEl(
    'svg',
    { class: `gap-icon gap-icon--${icon.tone}`, viewBox: '0 0 16 16', 'aria-hidden': 'true', focusable: 'false' },
    [svgEl('path', { d: icon.path })],
  );
  return el('p', { class: 'gap' }, [glyph, el('span', {}, [text])]);
}

/** Renders the result body for a view model. Displays only; never calculates. */
export function renderResult(resultBody: HTMLElement, vm: ViewModel): void {
  switch (vm.state) {
    case 'idle':
      resultBody.replaceChildren(resultMessage(vm.message));
      return;
    case 'pass-mark-empty':
      resultBody.replaceChildren(
        el('div', { class: 'outcome' }, [scoreNode(vm.score), el('p', { class: 'verdict-msg' }, [vm.verdictMessage])]),
      );
      return;
    case 'result':
      resultBody.replaceChildren(
        el('div', { class: 'outcome' }, [
          scoreNode(vm.score),
          verdictNode(vm.verdict, vm.verdictText),
          gapNode(vm.gapKind, vm.gapText),
        ]),
      );
      return;
  }
}

/** Builds the static card once from messages.ts and mounts it into `root`. Never calculates. */
export function renderShell(root: HTMLElement): ShellElements {
  const inputs = { earned: createInput('earned'), total: createInput('total'), pass: createInput('pass') };
  const errors = { earned: createErrorSlot('earned'), total: createErrorSlot('total'), pass: createErrorSlot('pass') };

  const resultBody = el('div', { class: 'result-body' }, [resultMessage(MESSAGES['M-1'])]);
  const status = el('div', { class: 'sr-only', role: 'status', 'aria-live': 'polite', 'aria-atomic': 'true' });
  const nextLearner = el('button', { class: 'btn', type: 'button', 'aria-keyshortcuts': 'Escape' }, [MESSAGES['M-25']]);

  const hintLead = MESSAGES['M-40'].slice(0, -ESC_KEY_LABEL.length);

  const card = el('article', { class: 'card', 'aria-labelledby': 'card-title' }, [
    el('header', { class: 'card-head' }, [
      el('p', { class: 'eyebrow' }, [MESSAGES['M-31']]),
      el('h1', { class: 'title', id: 'card-title' }, [MESSAGES['M-32']]),
      el('p', { class: 'sub' }, [MESSAGES['M-33']]),
    ]),
    el('div', { class: 'fields' }, [
      createField('earned', [MESSAGES['M-34']], inputs.earned, errors.earned),
      createField('total', [MESSAGES['M-35']], inputs.total, errors.total),
      createField('pass', [MESSAGES['M-36'], el('span', { class: 'sr-only' }, [MESSAGES['M-37']])], inputs.pass, errors.pass),
    ]),
    el('hr', { class: 'rule' }),
    el('section', { class: 'result', 'aria-labelledby': 'score-label' }, [
      el('p', { class: 'eyebrow', id: 'score-label' }, [MESSAGES['M-39']]),
      resultBody,
      status,
    ]),
    el('div', { class: 'actions' }, [
      nextLearner,
      el('span', { class: 'hint' }, [hintLead, el('kbd', {}, [ESC_KEY_LABEL])]),
    ]),
  ]);

  root.replaceChildren(el('main', { class: 'app' }, [card]));
  return { inputs, errors, resultBody, status, nextLearner };
}
import { formatScore } from '../logic/format';
import { gap, type Gap } from '../logic/gap';
import { isPass, scoreTenths } from '../logic/score';
import { announcementText, gapText, MESSAGES, scoreText } from '../messages';
import { validateInputs, type RawFields } from '../validation/validate';

// Pure: raw field text → what the result area shows (technical-design.md §State model). No DOM.

export type RawInputs = RawFields;

export type Verdict = 'pass' | 'fail';

export type GapKind = Gap['kind'];

/** `announcement` is the status text for screen readers; '' means nothing to announce. */
export type ViewModel =
  | { readonly state: 'idle'; readonly message: string; readonly announcement: string }
  | {
      readonly state: 'pass-mark-empty';
      readonly score: string;
      readonly verdictMessage: string;
      readonly announcement: string;
    }
  | {
      readonly state: 'result';
      readonly score: string;
      readonly verdict: Verdict;
      readonly verdictText: string;
      readonly gapKind: GapKind;
      readonly gapText: string;
      readonly announcement: string;
    };

// Idle is not announced (it is announced only after Next learner, S-4).
const IDLE: ViewModel = { state: 'idle', message: MESSAGES['M-1'], announcement: '' };

/** Recomputed from the three raw strings on every input event; no stored calculation state. */
export function toViewModel(raw: RawInputs): ViewModel {
  const fields = validateInputs(raw);
  // S-1 shows no score for invalid input; S-3 adds the error state, its messages and M-3.
  if (!fields.earned.ok || !fields.total.ok || !fields.pass.ok) return IDLE;

  const earned = fields.earned.value;
  const total = fields.total.value;
  if (earned === null || total === null) return IDLE;

  const score = formatScore(scoreTenths(earned, total));
  const passMark = fields.pass.value;
  if (passMark === null) {
    const verdictMessage = MESSAGES['M-2'];
    return { state: 'pass-mark-empty', score, verdictMessage, announcement: announcementText([scoreText(score), verdictMessage]) };
  }

  const verdict: Verdict = isPass(earned, total, passMark) ? 'pass' : 'fail';
  const verdictText = verdict === 'pass' ? MESSAGES['M-4'] : MESSAGES['M-5'];
  const marksGap = gap(earned, total, passMark);
  const gapLine = gapText(marksGap);
  return {
    state: 'result',
    score,
    verdict,
    verdictText,
    gapKind: marksGap.kind,
    gapText: gapLine,
    announcement: announcementText([scoreText(score), verdictText, gapLine]),
  };
}
import './styles/tokens.css';
import './styles/base.css';
import './styles/components.css';
import { mountApp } from './ui/app';

mountApp(document.getElementById('app'));
/**
 * Exact integer division for non-negative safe integers (ADR-002).
 * `a - a % b` is an exact multiple of `b`, so the division has no fractional part to round.
 */
export function floorDiv(a: number, b: number): number {
  return (a - (a % b)) / b;
}

/** ⌈a / b⌉ for non-negative safe integers: rounds up only when there is a remainder (ADR-002). */
export function ceilDiv(a: number, b: number): number {
  return floorDiv(a, b) + (a % b === 0 ? 0 : 1);
}
import { floorDiv } from './arith';

/** Formats a score in tenths of a percent with exactly 1 decimal place: 760 → "76.0", 0 → "0.0" (ADR-007). */
export function formatScore(tenths: number): string {
  return `${floorDiv(tenths, 10)}.${tenths % 10}`;
}

/** Inserts a comma every 3 digits into a string of digits: "1000000" → "1,000,000" (ADR-007, no Intl). */
function groupThousands(digits: string): string {
  return digits.replace(/\B(?=(\d{3})+$)/g, ',');
}

/**
 * Formats marks given in hundredths with at most 2 decimal places, trailing zeros trimmed and
 * comma thousands separators (A-11, ADR-007): 60 → "0.6", 600 → "6", 69_999_999 → "699,999.99".
 */
export function formatMarks(hundredths: number): string {
  const whole = groupThousands(String(floorDiv(hundredths, 100)));
  const fraction = String(hundredths % 100).padStart(2, '0').replace(/0+$/, '');
  return fraction === '' ? whole : `${whole}.${fraction}`;
}
import { ceilDiv, floorDiv } from './arith';

// Inputs are scaled integers (technical-design.md §Decimal strategy):
// E = marks earned × 100, T = total marks possible × 100, P = pass mark × 10.

/** The gap between marks earned and marks needed (P/100 × T); `h` is in hundredths of a mark. */
export type Gap =
  | { readonly kind: 'exact' }
  | { readonly kind: 'short'; readonly h: number }
  | { readonly kind: 'above'; readonly h: number }
  | { readonly kind: 'aboveTiny' };

/** D = E × 1000 − P × T is the exact gap in marks × 10⁵ (A-10, A-9). */
const MARKS_E5_PER_HUNDREDTH = 1000;

/**
 * Exact gap to the pass mark (A-10): a shortfall rounds UP to 2 dp (so it is never 0),
 * a surplus rounds DOWN to 2 dp, and a surplus under 0.01 is `aboveTiny`.
 */
export function gap(earned: number, total: number, passMark: number): Gap {
  const diff = earned * 1000 - passMark * total;
  if (diff === 0) return { kind: 'exact' };
  if (diff < 0) return { kind: 'short', h: ceilDiv(-diff, MARKS_E5_PER_HUNDREDTH) };
  const h = floorDiv(diff, MARKS_E5_PER_HUNDREDTH);
  return h === 0 ? { kind: 'aboveTiny' } : { kind: 'above', h };
}
import { floorDiv } from './arith';

// Inputs are scaled integers (technical-design.md §Decimal strategy):
// E = marks earned × 100, T = total marks possible × 100 (T > 0), P = pass mark × 10.

/** Score in tenths of a percent, rounded down (A-3): ⌊E × 1000 / T⌋. 17.5 of 23 → 760. */
export function scoreTenths(earned: number, total: number): number {
  return floorDiv(earned * 1000, total);
}

/** Pass ⇔ exact score ≥ pass mark (A-1, A-2), i.e. E × 1000 ≥ P × T, never the shown score. */
export function isPass(earned: number, total: number, passMark: number): boolean {
  return earned * 1000 >= passMark * total;
}

import { describe, expect, it } from 'vitest';
