/* Inline error slot: always present, keeps its height when empty */
.field-error {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  min-height: var(--error-slot-h);
  margin: var(--space-1) var(--space-0) var(--field-gap);
  font-size: var(--text-sm);
  line-height: var(--leading-tight);
  font-weight: var(--weight-medium);
  color: var(--color-error);
}

.alert-icon {
  flex: none;
  width: var(--icon-sm);
  height: var(--icon-sm);
  margin-top: calc((var(--text-sm) * var(--leading-tight) - var(--icon-sm)) / 2);
  fill: var(--color-error);
}

.alert-icon .alert-mark {
  fill: none;
  stroke: var(--color-surface);
  stroke-width: var(--icon-stroke-alert);
  stroke-linecap: round;
}

.alert-icon .alert-dot {
  fill: var(--color-surface);
}

/* ---- Divider ---- */
.rule {
  margin: var(--space-2) var(--space-0) var(--space-5);
  border: 0;
  border-top: var(--border-w) solid var(--color-border);
}

/* ---- Result area: reserved height so nothing below moves ---- */
.result-body {
  margin-top: var(--space-2);
  min-height: var(--result-min-h);
}

/* idle (M-1) and error (M-3) message */
.result-msg {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  font-size: var(--text-base);
  line-height: var(--leading-normal);
  color: var(--color-muted);
}

.result-msg .alert-icon {
  margin-top: calc((var(--text-base) * var(--leading-normal) - var(--icon-sm)) / 2);
}

