import { chromium } from '@playwright/test';
const out = process.argv[2];
const browser = await chromium.launch();
const states = { error: ['23.5', '23'], twoerrors: ['abc', '0'] };
const metrics = {};
for (const scheme of ['light', 'dark']) for (const width of [375, 1280]) for (const [name, [e, t]] of Object.entries(states)) {
  const page = await browser.newPage({ viewport: { width, height: 900 }, colorScheme: scheme });
  await page.goto('http://127.0.0.1:4173/');
  const btnIdle = (await page.getByRole('button').boundingBox()).y;
  await page.getByLabel('Total marks possible', { exact: true }).fill(t);
  await page.getByLabel('Marks earned', { exact: true }).fill(e);
  await page.waitForTimeout(100);
  const btnErr = (await page.getByRole('button').boundingBox()).y;
  const sw = await page.evaluate(() => document.documentElement.scrollWidth);
  metrics[`${name}-${width}-${scheme}`] = { btnIdle, btnErr, scrollWidth: sw };
  await page.screenshot({ path: `${out}/s3-${name}-${width}-${scheme}.png`, fullPage: true });
  await page.close();
}
console.log(JSON.stringify(metrics, null, 1));
await browser.close();
EOF
(npx vite preview --host 127.0.0.1 --port 4173 --strictPort > $SP/preview.log 2>&1 &); sleep 3; cp $SP/shots.mjs ./.shots.tmp.mjs && node ./.shots.tmp.mjs $SP; rm -f ./.shots.tmp.mjs; pkill -f "vite preview"; ls $SP/*.png

